q=dict(question='Can a nonvoter replication acknowledgement be consumed as sufficient support for a successful VerifyLeader authority check when no remote voter supports that check?',importance='VerifyLeader is documented as preventing stale FSM reads after leadership loss. If nonvoter support can substitute for voting authority, successful verification may be weaker than its public contract. This does not yet establish stale application output or conflicting committed logs.',source_ids=['i_verify','i_suffrage','s_verify','s_notify','s_future','s_loop','s_lease','s_leader','s_heartbeat'],participants=['local leader','remote voters','remote nonvoter'],objects=['verifyFuture','followerReplication.notify','latest configuration'],contexts=['Stable mixed voter/nonvoter membership in a single leadership tenure','per-operation verification registration and subsequent public completion'],event_paths=['VerifyLeader -> verifyLeader -> every replState.notify -> heartbeat/replication notifyAll -> verifyFuture.vote -> leaderLoop -> future.Error'],activity_classes=['A2'],behavior_ids=['b_contact','b_verify'],fact_ids=['f_verify_ack'],supporting_behavior_ids={'b_membership':'Replication includes nonvoters while voter membership determines quorum.','b_leadership':'Lease and role exit can prevent or invalidate success and must remain enabled in a real history.','b_campaign':'A legal elected prefix is needed before any authority-loss history.','b_append':'Actual receiver behavior determines whether nonvoter acknowledgement is produced.'},obligation_relation_kind='consumption',counterevidence=['checkLeaderLease counts only voters and can cause stepdown.','Negative acknowledgement can terminate verification early; normal replication can signal stale-term stepDown.','Log commitment filters voter IDs and is not directly affected by this tally.','A successful check before a competing election does not alone show lost authority or stale reads.'],unknowns=['Applicable requirement: derive authority-check eligibility from public VerifyLeader promise without equating it to log commitment.','Actual producer: run nonvoter receiver and correlate its real response with verification consumption.','Initial prefix: obtain a real elected leader and installed stable mixed membership.','Same-execution history: control partitions and finite delays while retaining lease, negative responses and regular replication protection.','Observed endpoint: measure the selected public future and, for any stronger stale-read claim, a competing authority or read history.'],priority=3,trigger_rationale='Source registration spans all replState entries and notifyAll/vote carry no suffrage check; quorumSize and independent lease path count only Voter entries. This is a concrete producer/consumer eligibility mismatch to investigate, not a proved violation.',disposition='concrete_suspicion',preferred_check='controlled_schedule')
